import collections, hashlib, json, os, re, subprocess
from pathlib import Path
from urllib.parse import unquote, urlsplit
ROOT=Path.cwd(); BASE='22551eed12b27a5db2a2fc4d1a26da5f67538c63'; PRIVATE=Path('/tmp/style-m3-d4-20261017')
REPORT=Path('docs/review/M3-D4-DOCS-2026-10-17.json')
DRAFT=Path('docs/review/M3-D4-REFRESH-2026-10-17.md')
MD=[Path(p) for p in ['docs/STYLE-M3-TASKS.md','docs/STYLE-M3-TESTS.md','docs/PROGRESS.md','docs/spec/STYLE-cli-design.md','docs/spec/STYLE-spec-rules.md','docs/spec/STYLE-spec-runtime.md','docs/spec/STYLE-spec-compiled.md','docs/STYLE-ADAPTERS-CURRENT.md',str(DRAFT)]]
ALLOWED={str(p) for p in MD}|{str(REPORT)}
def need(ok,msg):
 if not ok: raise AssertionError(msg)
def git(*args): return subprocess.check_output(['git',*args])
def sha(data): return hashlib.sha256(data).hexdigest()
def fences(source):
 out=[];blocks=[];active=None;body=[]
 for line in source.splitlines():
  f=re.match(r'^\s{0,3}(`{3,}|~{3,})(.*)$',line)
  if active is None and f: active=(f[1][0],len(f[1]),f[2].strip());body=[]
  elif active and f and f[1][0]==active[0] and len(f[1])>=active[1] and not f[2].strip(): blocks.append((active[2],'\n'.join(body)+'\n'));active=None
  elif active: body.append(line)
  else: out.append(line)
 need(active is None,'unclosed fence');return '\n'.join(out),blocks

def slugs(source):
 result=set();counts=collections.Counter()
 for line in fences(source)[0].splitlines():
  m=re.match(r'^#{1,6}\s+(.+?)\s*#*$',line)
  if m:
   h=re.sub(r'<[^>]+>','',m[1]).strip().lower();h=re.sub(r'[^\w\- ]','',h).replace(' ','-')
   result.add(h+(f'-{counts[h]}' if counts[h] else ''));counts[h]+=1
 return result

def entries(source):
 rows=re.findall(r'^- \[([ x~!?])\] \*\*(M3-[A-Z0-9-]+) (.+?)\*\*(.*)$',source,re.M)
 need(len(rows)==len({r[1] for r in rows}),'duplicate id');return {i:(s,t,b) for s,i,t,b in rows}

def refs(source):
 def expand(m):
  prefix,first,middle,last=m.groups();need(middle in (None,prefix.split('-')[-1]),'range')
  width=len(first) if first.startswith('0') else 0
  return ' '.join(prefix+str(i).zfill(width) for i in range(int(first),int(last)+1))
 source=re.sub(r'(M3-(?:[A-Z]+-)*[A-Z]*)(\d+)[–—]([A-Z]+-?)?(\d+)',expand,source)
 return set(re.findall(r'\bM3-[A-Z0-9]+(?:-[A-Z0-9]+)*\b',source))

if not REPORT.exists(): REPORT.write_text('{}\n')
old_progress=git('show',BASE+':docs/PROGRESS.md');progress=Path('docs/PROGRESS.md').read_bytes()
need(progress.startswith(old_progress) and len(progress)>len(old_progress),'progress not append-only')
documents={p:p.read_text() for p in MD};documents[Path('docs/PROGRESS.md')]=progress[len(old_progress):].decode()
links=external=shells=json_blocks=0
for path,source in documents.items():
 need(source.endswith('\n') and all(line==line.rstrip() for line in source.splitlines()),str(path)+': whitespace')
 visible,blocks=fences(source)
 for lang,code in blocks:
  if lang in {'sh','bash','zsh'}:
   r=subprocess.run(['zsh','-n'],input=code,text=True,capture_output=True);need(r.returncode==0,str(path)+': shell syntax '+r.stderr);shells+=1
  if lang=='json': json.loads(code);json_blocks+=1
 for m in re.finditer(r'\[[^\]\n]+\]\(([^)\n]+)\)',visible):
  target=m[1].strip().strip('<>');u=urlsplit(target)
  if u.scheme or u.netloc: external+=1;continue
  dest=(path.parent/unquote(u.path)).resolve() if u.path else path.resolve();need(dest.exists(),str(path)+': missing '+target)
  if u.fragment: need(unquote(u.fragment) in slugs(dest.read_text()),str(path)+': missing anchor '+target)
  links+=1

task_path=Path('docs/STYLE-M3-TASKS.md');test_path=Path('docs/STYLE-M3-TESTS.md')
tasks=entries(documents[task_path]);tests=entries(documents[test_path]);old_tasks=entries(git('show',BASE+':'+str(task_path)).decode());old_tests=entries(git('show',BASE+':'+str(test_path)).decode())
need(len(tasks)==44 and tasks.keys()==old_tasks.keys(),'task inventory');need(len(tests)==39 and tests.keys()==old_tests.keys(),'test inventory')
for i,row in tasks.items(): need(row[0]==('~' if i=='M3-D4' else old_tasks[i][0]),i+': state')
for i,row in tests.items(): need(row[0]==old_tests[i][0],i+': state')
deps={};old_deps={};mapped=set()
for i,(_,_,body) in tasks.items():
 for field in ['目标','依赖：','产出：','测试：']: need(field in body,i+': '+field)
 deps[i]=refs(re.search(r'依赖：([^。；]+)',body)[1]);old_deps[i]=refs(re.search(r'依赖：([^。；]+)',old_tasks[i][2])[1]);need(deps[i]<=tasks.keys(),i+': dependency')
 targets=refs(re.search(r'测试：([^。；]+)',body)[1]);need(targets and targets<=tests.keys(),i+': tests');mapped|=targets
need(mapped==tests.keys(),'test coverage')
need(deps['M3-D4']=={'M3-T30'} and old_deps['M3-D4']=={'M3-T32'},'D4 approved scope order')
for i in tasks:
 if i!='M3-D4': need(deps[i]==old_deps[i],i+': unrelated dependency change')
for i,(_,_,body) in tests.items():
 m=re.match(r'（([^）]+)）',body);need(m and refs(m[1]) and refs(m[1])<=tasks.keys(),i+': task mapping')
def ancestors(i,visiting=None):
 visiting=set() if visiting is None else visiting;need(i not in visiting,'dependency cycle');visiting=visiting|{i}
 return deps[i]|set().union(*(ancestors(d,visiting) for d in deps[i]))
for i in tasks:
 chain=ancestors(i)
 if re.fullmatch(r'M3-[DT]\d+',i) and i not in {'M3-D0','M3-T00'}: need('M3-T00' in chain,i+': architecture dependency')
need('M3-CARRY-01' not in ancestors('M3-FINAL'),'count carry became blocking')
rows=re.findall(r'^\| (A9-\d{2}) \| \[([ x])\] \|',documents[DRAFT],re.M)
need(rows==[(f'A9-{i:02d}',' ') for i in range(1,13)],'A9 cases/states')
need('用户评审通过后进入实现' in documents[task_path] and '待用户评审，未允许进入 T40 实现' in documents[DRAFT],'review boundary')
for i in ['M3-T31','M3-T32']: need(tasks[i][0]==' ' and '暂缓' in tasks[i][2],i+' deferral')
need(tasks['M3-D3'][0]=='~' and tasks['M3-T40'][0]==' ' and tests['M3-A9'][0]==' ','unfinished scope')
changed=set(git('diff','--name-only',BASE).decode().splitlines())|set(git('ls-files','--others','--exclude-standard').decode().splitlines());need(changed==ALLOWED,'unexpected changes '+str(changed^ALLOWED))
protected=archives=historical_m3=fixtures=production=0
for raw in git('ls-tree','-rz','--full-tree',BASE).split(b'\0'):
 if not raw: continue
 meta,name=raw.split(b'\t',1);mode,kind,oid=meta.decode().split();name=name.decode()
 if name in ALLOWED: continue
 data=os.readlink(name).encode() if mode=='120000' else Path(name).read_bytes()
 need(hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()==oid,'protected '+name)
 protected+=1;archives+=bool(re.match(r'docs/(?:STYLE-M[12]|review/M[12])',name));historical_m3+=name.startswith('docs/review/M3') and name.endswith('.json');fixtures+=name.startswith('testdata/');production+=name.endswith('.go') and not name.endswith('_test.go')
need(archives==77,'archive count')
source_paths=['core/state/state.go','core/state/dedup.go','core/state/snapshot.go','core/state/stats.go','core/state/stats_read.go','core/engine/process.go','core/engine/load.go','core/engine/trace.go','core/compile/types.go','core/compile/dedup.go','core/plan/system.go','core/plan/events.go','core/spec/merge.go','core/spec/validate_rules.go','core/tokens/installed.go','internal/runtime/runtime.go','internal/adapter/claude/runtime.go','internal/adapter/claude/adapter.go','internal/adapter/codex/runtime.go','agenthooks/codec_codex.go','agenthooks/codec_claudecode.go','agenthooks/event.go','schema/index.schema.json']
source_hashes={p:sha(Path(p).read_bytes()) for p in source_paths}
run_results={}
for name in ['baseline-tests','baseline-probe']:
 r=json.loads((PRIVATE/(name+'.json')).read_text());need(r['exit_code']==0,'run failure '+name)
 r['private_log']=str(PRIVATE/(name+'.log'));r['log_sha256']=sha(Path(r['private_log']).read_bytes());run_results[name]=r
events=[json.loads(l) for l in (PRIVATE/'baseline-tests.log').read_text().splitlines() if l.startswith('{')]
counts=collections.Counter(e['Action'] for e in events if e.get('Test'));need(counts['pass']==307 and counts['fail']==counts['skip']==0,'baseline tests')
packages=[e['Package'] for e in events if e['Action']=='pass' and not e.get('Test')];need(len(packages)==5 and not any('(cached)' in e.get('Output','') for e in events),'baseline packages/cache')
probe=json.loads((PRIVATE/'baseline-probe.log').read_text());need(len(probe['cases'])==8,'probe cases')
sources=[]
for label,name,url in [('codex','codex-hooks.html','https://developers.openai.com/codex/hooks'),('claude','claude-hooks.md','https://code.claude.com/docs/en/hooks.md')]:
 path=PRIVATE/name;data=path.read_bytes();need(len(data)>1000,'empty official page')
 terms=['turn_id','UserPromptSubmit','compact'] if label=='codex' else ['prompt_id','UserPromptSubmit','first user input']
 need(all(t in data.decode() for t in terms),'official basis '+label)
 sources.append({'provider':label,'url':url,'accessed':'2026-10-17','sha256':sha(data),'bytes':len(data),'private_copy':str(path),'verified_terms':terms,'scope':'documentation facts only; no native runtime or latest-version claim'})
fetch_attempts=json.loads((PRIVATE/'fetch-attempts.json').read_text())
need([r['exit_code'] for r in fetch_attempts]==[6,0,0],'fetch results')
git('diff','--check',BASE)
# A new untracked file is not covered by git diff --check; the Markdown loop above
# checks whitespace for every allowed Markdown file, and the final staged check
# additionally covers the JSON report and every tracked/new path before commit.
report={'format':1,'task':'M3-D4','date':'2026-10-17','status':'passed','meaning':'design documentation and existing-behavior investigation checks only','design_status':'pending_user_review','implementation_started':False,'source_base':BASE,'scope_change':{'authorization':'继续推进其他M3阶段计划','dependency_before':['M3-T32'],'dependency_after':['M3-T30'],'deferred':['M3-T31/M3-A7','M3-T32/M3-A8'],'routes_for_T40':['codex-user','codex-plugin','codex-project','claude-user','claude-project']},'verification':{'local_links_and_anchors':links,'external_reference_occurrences':external,'official_pages_refetched':len(sources),'markdown_fences':'balanced','shell_blocks_syntax_checked':shells,'json_blocks_checked':json_blocks,'task_entries':44,'test_entries':39,'dependency_graph':'acyclic; only D4 prerequisite changed','state_changes_only':['M3-D4 [ ] -> [~]'],'test_states_unchanged':True,'A9_subcases':12,'A9_subcases_status':'all pending','deferred_and_real_states_unchanged':True,'PROGRESS_append_only':True,'PROGRESS_prefix_sha256':sha(old_progress),'M1_M2_archives_unchanged':archives,'historical_M3_JSON_unchanged':historical_m3,'all_existing_testdata_files_unchanged':fixtures,'production_go_files_unchanged':production,'protected_baseline_files_unchanged':protected,'git_diff_check':'passed; baseline combined diff including staged files','new_markdown_whitespace':'passed; tracked and untracked','final_staged_diff_check_required':True},'baseline_regression':{'test_pass_events_including_groups':307,'failed':0,'skipped':0,'packages':packages,'cached':False,'new_refresh_tests_run':False},'existing_behavior_probe':{'cases':probe['cases'],'source_sha256':sha((PRIVATE/'baseline-probe.go').read_bytes()),'source':(PRIVATE/'baseline-probe.go').read_text(),'reproduction':'Extract source to a temporary .go file, then run go run on that file from the repository with the recorded temporary caches and cleaned environment. This confirms existing behavior only.'},'runs':run_results,'runner':{'source_sha256':sha((PRIVATE/'run.py').read_bytes()),'source':(PRIVATE/'run.py').read_text(),'cache_origin':'reuse of existing temporary A6 caches; go test -count=1 prevents test-result caching'},'official_sources':sources,'official_fetch_attempts':fetch_attempts,'source_sha256':source_hashes,'document_sha256':{str(p):sha(p.read_bytes()) for p in MD},'A9_acceptance':[{'id':i,'status':'pending'} for i,_ in rows],'changes':sorted(changed),'not_run':['new refresh implementation tests','full two-module regression/vet/race (no production changes)','real Codex or Claude harness','remote models','Claude cloud or plugin','Windows native execution','remote CI','official counting (both remain 0/40)']}
report['documentation_check']={'command':['python3',str(PRIVATE/'check-docs.py')],'source_sha256':sha(Path(__file__).read_bytes()),'source':Path(__file__).read_text(),'reproduction':'Extract this source to a temporary Python file and run from the repository. It compares the working files to source_base and writes the report. A final staged diff --check is separate.'}
REPORT.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
print(json.dumps(report['verification'],ensure_ascii=False,indent=2))
print('baseline: 307 pass / 0 fail / 0 skip; 8 probes; no new implementation')
